  str_mail_title_30003 = "Recompensas da Coleção de Culinária",
  str_mail_detail_30003 = "Você tem recompensas da Coleção de Culinária não reclamadas esperando por você! Por favor, verifique o mais cedo possível!",
  str_mail_title_33200019 = "Recompensas de Spire ajustadas",
  str_mail_detail_33200019 = "Caro navegador,\nAjustamos a 1ª Recompensa Completa do Spire System na atualização de 6 de julho.\nSeu progresso no Spire Challenge antes da atualização é o seguinte:\nNível de água {1}, Fogo: Nível {2}, Floresta: Nível {3}, Trovão: Nível {4}.\n\nCom base nas primeiras recompensas concluídas após o ajuste e no progresso do desafio atual, você receberá as seguintes recompensas:\n(As 1ª Recompensas Clear dos 4 Spires serão emitidas juntas)\n\nSe você tiver alguma dúvida, entre em contato conosco através do nosso atendimento ao cliente oficial. Obrigado por apoiar o Alchemy Stars.",
  str_mail_gm_season = "Eve",
  str_mail_title_season = "Eve embalou essas coisas para você!",
  str_mail_detail_season_1 = "Navegador, você esqueceu alguma coisa? Percebi que alguns itens estavam prestes a expirar, então troquei por algo útil. Esses itens já devem estar no seu Armazém... De qualquer forma, aqui estão os detalhes, não deixe de conferir!\n\n{1} ×{2} foram trocados por {3} ×{4}",
  str_mail_detail_season_2 = "Navegador, você esqueceu alguma coisa? Percebi que alguns itens estavam prestes a expirar, então troquei por algo útil. Esses itens já devem estar no seu Armazém... De qualquer forma, aqui estão os detalhes, não deixe de conferir!\n\n{3} ×{4} foram trocados por {5} ×{6}\n{1} ×{2} foram trocados por{7} ×{8}",
  str_mail_s2_gm_season = "Irridon",
  str_mail_s2_title_season = "Por favor, não esqueça destes!",
  str_mail_s2_detail_season_1 = "Ei, Navegador, muito obrigado por ajudar no sonho ultimamente. Tomei a liberdade de trocar alguns itens que você pode achar inconveniente carregar por outros mais práticos, que armazenei no seu Armazém. Abaixo estão os detalhes para sua referência.\n\n{1}×{2} foram trocados por {3}×{4}.",
  str_mail_s2_detail_season_2 = "Ei, Navegador, muito obrigado por ajudar no sonho ultimamente. Tomei a liberdade de trocar alguns itens que podem ser inconvenientes para carregar por outros mais práticos, que armazenei no seu Armazém. Abaixo estão os detalhes para sua referência.\n\n{3}×{4} foram trocados por {5}×{6}.\n{1}×{2} foram trocados por {7}×{8}",
  str_mail_title_taskreward = "Recompensas Não-retiradas",
  str_mail_detail_taskreward = "O evento {1} acabou! Aqui estão as recompensas que você não conseguiu retirar durante o evento!",
